  @Override
  @Transactional
  public void run() {
    install("sesamo");
  }

  private final UserWriteRepositoryGateway users;
  private final RoleWriteRepositoryGateway roles;
  private final TenantWriteRepositoryGateway tenants;
  private final TrustedClientWriteRepositoryGateway clients;
  private final RelyingPartyWriteRepositoryGateway parties;
  private final UserRoleAssignamentWriteRepositoryGateway rolesAssignament;
  private final UserGroupMembershipWriteRepositoryGateway groupsMembership;
  private final ApiKeyClientWriteRepositoryGateway apiKeys;

  void install(String password) {
    if (users.countForUpdate(UserFilter.builder().build()) != 0) {
      return;
    }

    RelyingPartyChangeSet party = new RelyingPartyChangeSet().newUid().code("lughauth-api")
        .apiKey("1111").enabled(Boolean.TRUE);

    AllowedRedirects localhost =
        AllowedRedirects.builder().newUid().url("http://localhost:4200/*").build();

    TrustedClientChangeSet client = new TrustedClientChangeSet().newUid().code("lughauth-ui")
        .allowAllScopes(Boolean.TRUE).secretOauthPlain("123456").publicAllow(Boolean.TRUE)
        .tokenEndpointAuthMethod("client_secret_post").m2mTokenTtlSeconds(3600)
        .allowedRedirects(List.of(localhost)).enabled(Boolean.TRUE);

    RoleChangeSet adminRole = new RoleChangeSet().newUid().name("ADMIN");
    RoleChangeSet rootRole = new RoleChangeSet().newUid().name("ROOT");
    RoleChangeSet iamRole = new RoleChangeSet().newUid().name("IAM");

    TenantChangeSet tenant = new TenantChangeSet().newUid().name("main").domain("main")
        .enabled(Boolean.TRUE).root(Boolean.TRUE).markForDelete(Boolean.FALSE);

    UserChangeSet root = new UserChangeSet().newUid().name("ROOT").passwordPlain(password)
        .tenant(tenant).enabled(true).useSecondFactors(false);

    RelyingParty createdParty = parties.create(RelyingParty.create(party).enable());
    TrustedClient createdClient = clients.create(TrustedClient.create(client).enable());
    Role createdAdminRole = roles.create(Role.create(adminRole));
    Role createdRootRole = roles.create(Role.create(rootRole));
    Role createdIamRole = roles.create(Role.create(iamRole));
    tenants.create(Tenant.create(tenant).enable());
    User createdRoot = users.create(User.create(root).enable());

    UserGroupMembershipChangeSet userRelyGroups = new UserGroupMembershipChangeSet().newUid()
        .user(createdRoot).relyingParty(createdParty).groups("root");
    groupsMembership.create(UserGroupMembership.create(userRelyGroups));

    UserGroupMembershipChangeSet userClientGroups = new UserGroupMembershipChangeSet().newUid()
        .user(createdRoot).trustedClient(createdClient).groups("root");
    groupsMembership.create(UserGroupMembership.create(userClientGroups));


    UserRoleAssignamentChangeSet adminAssign = new UserRoleAssignamentChangeSet().newUid()
        .user(createdRoot).roles(List.of(Roles.builder().newUid().role(createdAdminRole).build()));
    rolesAssignament.create(UserRoleAssignament.create(adminAssign));

    UserRoleAssignamentChangeSet rootAssign = new UserRoleAssignamentChangeSet().newUid()
        .user(createdRoot).roles(List.of(Roles.builder().newUid().role(createdRootRole).build()));
    rolesAssignament.create(UserRoleAssignament.create(rootAssign));

    UserRoleAssignamentChangeSet iamAssign = new UserRoleAssignamentChangeSet().newUid()
        .user(createdRoot).roles(List.of(Roles.builder().newUid().role(createdIamRole).build()));
    rolesAssignament.create(UserRoleAssignament.create(iamAssign));

    ApiKeyClientChangeSet collectorApiKey =
        new ApiKeyClientChangeSet().newUid().code("Initial collector")
            .key("hcaik_01jtteh99vbsv4qrj22trvh3wg35g1n4tgkcxzgqv0034y2cby7dceaf43")
            .scopes("collect").enabled(true);
    apiKeys.create(ApiKeyClient.create(collectorApiKey).enable());

    ApiKeyClientChangeSet syncApiKey =
        new ApiKeyClientChangeSet().newUid().code("Initial syn client")
            .key("sck_01jtteh99vbsv4qrj22trvh3wg35g2n3tgkcxngqv0034y2cby7dceaf43").scopes("sync")
            .enabled(true);
    apiKeys.create(ApiKeyClient.create(syncApiKey).enable());

  }
